import java.util.HashSet;
import java.util.Set;

class Solution {
    public long matrixSumQueries(int n, int[][] queries) {
        Set<Integer> seenRows = new HashSet<>();
        Set<Integer> seenCols = new HashSet<>();
        long total = 0;
        for (int i = queries.length - 1; i >= 0; i--) {
            int type = queries[i][0];
            int idx = queries[i][1];
            int val = queries[i][2];
            if (type == 0) {
                if (!seenRows.contains(idx)) {
                    seenRows.add(idx);
                    total += (long) val * (n - seenCols.size());
                }
            } else {
                if (!seenCols.contains(idx)) {
                    seenCols.add(idx);
                    total += (long) val * (n - seenRows.size());
                }
            }
        }
        return total;
    }
}

var matrixSumQueries = function(n, queries) {
